const fruits={2:'Dragon Fruit',3:'Bamboo Shoot',4:'Berry',5:'Carrot',6:'Phantom Fruit',7:'Clocko Fruit'};
const el=(tag,text)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;return n;};
export function installUIDListing({supabase,status}){
 const holder=document.getElementById('approved-list'),message=document.getElementById('uid-list-status');let rows=[],view='listed',busy=false;
 const dialog=el('dialog');dialog.className='uid-edit-dialog';dialog.setAttribute('aria-labelledby','uid-edit-title');
 const heading=el('header');heading.className='standard-modal-header';const title=el('h2');title.id='uid-edit-title';const close=el('button','×');close.type='button';close.className='standard-modal-close';close.setAttribute('aria-label','Close dialog');close.onclick=()=>dialog.close();heading.append(title,close);
 const form=el('form'),fields=el('div');fields.className='uid-edit-fields';const input=(labelText,type,max)=>{const label=el('label',labelText),n=el(type==='textarea'?'textarea':'input');if(type!=='textarea')n.type=type;if(max)n.maxLength=max;label.append(n);fields.append(label);return n;};
 const uid=input('Farm UID','text',20);uid.inputMode='numeric';uid.pattern='[1-9][0-9]{0,19}';uid.required=true;
 const fruitLabel=el('label','Fruit'),crop=el('select');for(const [id,name] of Object.entries(fruits)){const o=el('option',name);o.value=id;crop.append(o)}fruitLabel.append(crop);fields.append(fruitLabel);
 const bonus=input('Support bonus (%)','number');bonus.min=0;bonus.max=263;bonus.step=1;bonus.required=true;
 const note=input('Admin notes','textarea',1000);note.rows=3;
 const actions=el('div');actions.className='uid-dialog-actions';const save=el('button','Save'),feedback=el('p');save.type='submit';feedback.setAttribute('role','status');actions.append(save,feedback);form.append(fields,actions);dialog.append(heading,form);document.body.append(dialog);let editing=null,mode='create';
 async function rpc(action,payload={}){const {data,error}=await supabase.rpc('admin_farm_listings',{p_action:action,p_payload:payload});if(error)throw Error(error.message);return data;}
 async function refresh(){try{rows=await rpc('load');message.textContent='';paint()}catch(e){message.textContent='UID Listing could not load. '+e.message;throw e;}}
 function lock(value){busy=value;holder.querySelectorAll('button').forEach(b=>b.disabled=value);document.getElementById('uid-create').disabled=value;save.disabled=value;}
 async function mutate(action,row){if(busy)return;if(action==='purge'&&!confirm('Permanently delete UID '+row.game_uid+' for '+fruits[row.crop_id]+'? This also removes its activity reports.'))return;lock(true);try{await rpc(action,{id:row.id});await refresh();status('UID listing updated.')}catch(e){message.textContent=e.message;}finally{lock(false)}}
 function open(row,action){editing=row;mode=action;title.textContent=action==='create'?'Create UID':action==='notes'?'Admin notes':'Edit UID';uid.value=row?.game_uid||'';crop.value=row?.crop_id||2;bonus.value=row?.bonus??263;note.value=row?.admin_note||'';for(const field of [uid,crop,bonus]){field.disabled=action==='notes';field.closest('label').hidden=action==='notes';}feedback.textContent='';save.textContent=action==='create'?'Create listing':'Save changes';dialog.showModal();(action==='notes'?note:uid).focus();}
 form.onsubmit=async e=>{e.preventDefault();if(busy)return;lock(true);try{await rpc(mode,{id:editing?.id,uid:uid.value.trim(),crop:Number(crop.value),bonus:Number(bonus.value),note:note.value});dialog.close();await refresh();status(mode==='create'?'UID listed.':'UID listing saved.');}catch(e){feedback.textContent=e.message;}finally{lock(false)}};
 function paint(){const shown=rows.filter(r=>view==='deleted'?!!r.deleted_at:!r.deleted_at);const wrap=el('div');wrap.className='uid-table-wrap';const table=el('table');table.className='uid-table';const head=el('thead'),tr=el('tr');for(const text of ['Farm UID','Fruit','Bonus','Status','Actions'])tr.append(el('th',text));head.append(tr);table.append(head);const body=el('tbody');for(const r of shown){const row=el('tr');for(const text of [r.game_uid,fruits[r.crop_id]||'Unknown fruit','+'+r.bonus+'%',r.deleted_at?'Deleted':r.enabled?'Listed':'Hidden'])row.append(el('td',text));const cell=el('td');cell.className='uid-row-actions';for(const [text,action] of [['Edit','edit'],[r.deleted_at?'Restore':r.enabled?'Hide':'Show',r.deleted_at?'restore':r.enabled?'hide':'show'],['Delete',r.deleted_at?'purge':'delete'],['Notes','notes']]){const b=el('button',text);b.type='button';b.disabled=busy;if(action==='purge')b.className='uid-danger';if(action==='notes'&&r.admin_note)b.title=r.admin_note;b.onclick=()=>['edit','notes'].includes(action)?open(r,action):mutate(action,r);cell.append(b)}row.append(cell);body.append(row)}table.append(body);wrap.append(table);holder.replaceChildren(wrap);if(!shown.length)holder.append(el('p',view==='deleted'?'No deleted listings.':'No UID listings yet.'));for(const b of document.querySelectorAll('[data-uid-view]')){b.setAttribute('aria-pressed',String(b.dataset.uidView===view));const count=rows.filter(r=>b.dataset.uidView==='deleted'?!!r.deleted_at:!r.deleted_at).length;b.textContent=(b.dataset.uidView==='deleted'?'Deleted':'Listed')+' ('+count+')';}}
 document.getElementById('uid-create').onclick=()=>open(null,'create');for(const b of document.querySelectorAll('[data-uid-view]'))b.onclick=()=>{view=b.dataset.uidView;paint()};return {refresh};
}
